const bugId      = String($input.item.json.body?.objectID || '').trim();

// ── 解析禅道产品 ID（格式 ",52," → "52"）───────────────────────────────────
const rawProduct    = String($input.item.json.body?.product || '');
const productIdMatch = rawProduct.match(/\d+/);
const productId     = productIdMatch ? productIdMatch[0] : '';

// body.project / body.projectName 作为备用键
const projectKey = String($input.item.json.body?.project   ||
                          $input.item.json.body?.projectName || '').trim();

// ── 读取上游配置节点 ─────────────────────────────────────────────────────────
const cfg = $input.item.json._config || {};
const sec = $input.item.json._secrets || {};

const projects     = cfg.projects     || {};
const productIdMap = cfg.productIdMap || {};
const defaults     = cfg.defaults     || {};

// ── 查找项目配置（优先产品ID，回退项目名）───────────────────
const projCfg = (productId && productIdMap[productId])
             || (projectKey && projects[projectKey])
             || {};

const resolvedProject = projCfg.displayName || projectKey || ('productId=' + productId) || '未知项目';

const sourceRepo      = projCfg.repoPath        || '';
const gitlabProjectId = projCfg.gitlabProjectId || '';
const projectOwner    = projCfg.projectOwner    || defaults.projectOwner || '';
const targetBranch    = projCfg.targetBranch    || defaults.targetBranch || 'develop';
const worktreeBase    = defaults.worktreeBase   || '/tmp/n8n-worktrees';
const worktreeDir     = worktreeBase + '/bugfix-' + bugId;

const zentaoUrl      = sec.zentaoUrl      || '';
const zentaoAccount  = sec.zentaoAccount  || '';
const zentaoPassword = sec.zentaoPassword || '';
const gitlabUrl      = sec.gitlabUrl      || '';
const gitlabToken    = sec.gitlabToken    || '';

const credFile = '/tmp/n8n-creds-' + bugId + '.env';
const bugFile  = worktreeDir + '/.ai-fix/bug.json';
const skillPy  = '/root/.claude/skills/zc-bug-fix/scripts/bugfix_flow.py';

function shellSingleQuote(v) {
  return "'" + String(v).replace(/'/g, "'\\''") + "'";
}

function buildCreateCredsCmd() {
  const pairs = [
    ['ZENTAO_URL',        zentaoUrl],
    ['ZENTAO_ACCOUNT',    zentaoAccount],
    ['ZENTAO_PASSWORD',   zentaoPassword],
    ['GITLAB_URL',        gitlabUrl],
    ['GITLAB_TOKEN',      gitlabToken],
    ['GITLAB_PROJECT_ID', gitlabProjectId],
    ['PROJECT_OWNER',     projectOwner],
    ['TARGET_BRANCH',     targetBranch],
    ['ALLOW_GIT_PUSH',    '1'],
  ];
  const lines = ['rm -f ' + shellSingleQuote(credFile)];
  for (const [k, v] of pairs) {
    lines.push('printf "%s\\n" ' + shellSingleQuote(k + '=' + v) + ' >> ' + shellSingleQuote(credFile));
  }
  return lines.join('\n');
}

function buildCommentCommand(commentText, tmpSuffix) {
  if (!/^\d+$/.test(bugId)) return 'echo "STATUS=COMMENT_SKIPPED"';
  const tmp = '/tmp/zentao-' + tmpSuffix + '-' + bugId + '.txt';
  return [
    'echo ' + shellSingleQuote(commentText) + ' > ' + tmp,
    'ZC_BUG_FIX_CONFIG=' + shellSingleQuote(credFile) +
      ' python3 ' + skillPy + ' zentao-comment ' +
      shellSingleQuote(bugId) + ' ' + tmp + ' 2>/dev/null || true',
    'rm -f ' + tmp,
    'echo "STATUS=COMMENT_DONE"'
  ].join('\n');
}

let setupLines = [];
if (!bugId || !/^\d+$/.test(bugId)) {
  setupLines = ['echo "STATUS=FAIL"', 'echo "SUMMARY=invalid or missing bug id"'];
} else if (!sourceRepo) {
  const hint = productId
    ? 'productId=' + productId + ' (body.product=' + rawProduct + ')'
    : (projectKey ? 'projectKey=' + projectKey : 'no project/product in body');
  setupLines = [
    'echo "STATUS=FAIL"',
    'echo "SUMMARY=no repo configured for ' + hint + '; add it in [[项目配置] 项目配置] node (column [5] for productId)"',
  ];
} else if (!zentaoUrl || !gitlabToken) {
  setupLines = [
    'echo "STATUS=FAIL"',
    'echo "SUMMARY=missing credentials; fill in [[密钥配置] 密钥配置] node"'
  ];
} else {
  setupLines = [
    'export ZENTAO_URL='         + shellSingleQuote(zentaoUrl),
    'export ZENTAO_ACCOUNT='     + shellSingleQuote(zentaoAccount),
    'export ZENTAO_PASSWORD='    + shellSingleQuote(zentaoPassword),
    'export GITLAB_URL='         + shellSingleQuote(gitlabUrl),
    'export GITLAB_TOKEN='       + shellSingleQuote(gitlabToken),
    'export GITLAB_PROJECT_ID='  + shellSingleQuote(gitlabProjectId),
    'export PROJECT_OWNER='      + shellSingleQuote(projectOwner),
    'export TARGET_BRANCH='      + shellSingleQuote(targetBranch),
    'export ALLOW_GIT_PUSH=1',
    'CONFIG_FILE=' + shellSingleQuote(sourceRepo + '/.claude/ai-fix.env'),
    'if [ -f "$CONFIG_FILE" ]; then set -a; . "$CONFIG_FILE" >/dev/null 2>&1 || true; set +a; fi',
    'BUG_ID=' + shellSingleQuote(bugId),
    'WORKTREE_DIR=' + shellSingleQuote(worktreeDir),
    'SOURCE_REPO=' + shellSingleQuote(sourceRepo),
    'WORKTREE_BASE=' + shellSingleQuote(worktreeBase),
    'LOCK_DIR="/tmp/ai-fix-bug-${BUG_ID}.lock"',
    'if ! mkdir "$LOCK_DIR" 2>/dev/null; then',
    '  echo "STATUS=FAIL"',
    '  echo "SUMMARY=another ai fix is already running for this bug"',
    '  exit 0',
    'fi',
    "trap 'rmdir \"$LOCK_DIR\" >/dev/null 2>&1' EXIT",
    'if [ ! -d "$SOURCE_REPO/.git" ]; then echo "STATUS=FAIL"; echo "SUMMARY=source repo missing at $SOURCE_REPO"; exit 0; fi',
    'mkdir -p "$WORKTREE_BASE"',
    'if ! git -C "$SOURCE_REPO" fetch origin ' + shellSingleQuote(targetBranch) + ' >/dev/null 2>&1; then echo "STATUS=FAIL"; echo "SUMMARY=git fetch origin ' + targetBranch + ' failed"; exit 0; fi',
    'git -C "$SOURCE_REPO" worktree remove --force "$WORKTREE_DIR" >/dev/null 2>&1 || true',
    'rm -rf "$WORKTREE_DIR"',
    'if ! git -C "$SOURCE_REPO" worktree add -B "bugfix/${BUG_ID}" "$WORKTREE_DIR" "origin/' + targetBranch + '" >/dev/null 2>&1; then',
    '  echo "STATUS=FAIL"',
    '  echo "SUMMARY=git worktree creation failed"',
    '  exit 0',
    'fi',
    'echo "STATUS=SETUP_OK"',
    'mkdir -p "${WORKTREE_DIR}/.ai-fix"',
    'echo ".ai-fix/" >> "${WORKTREE_DIR}/.gitignore"',
    '# 预读取禅道 Bug（ Claude 直接使用）',
    'ZC_BUG_FIX_CONFIG=' + shellSingleQuote(credFile) + ' python3 ' + shellSingleQuote(skillPy) + ' fetch ' + shellSingleQuote(bugId) +
      ' > ' + shellSingleQuote(bugFile) + ' 2>&1',
    'if python3 -c "import json,sys; d=json.load(open(' + shellSingleQuote(bugFile) + ')); sys.exit(0 if d.get(\'status\')==\'success\' else 1)" 2>/dev/null; then',
    '  echo "STATUS=BUG_PREFETCHED"',
    'else',
    '  echo "STATUS=BUG_FETCH_WARN (Claude will re-fetch)"',
    'fi',
  ];
}
const setupCommand = setupLines.join('\n');

const credPrefix = 'ZC_BUG_FIX_CONFIG=' + shellSingleQuote(credFile);
const issueDescFile = worktreeDir + '/.ai-fix/issue-desc.md';
const mrDescFile    = worktreeDir + '/.ai-fix/mr-desc.md';

const prompt = [
  '你正在执行 zc-bug-fix skill 的 Server Unattended Mode。',
  '这是由 n8n 触发的无人值守修复流程，不要向用户提问，不要等待确认。',
  '',
  '目标：处理禅道 Bug #' + bugId + '（项目：' + resolvedProject + '）',
  '工作目录：' + worktreeDir + '（独立 git worktree，已基于 origin/' + targetBranch + ' 创建）',
  '凭据文件：' + credFile + '（n8n 已写入，不要删除）',
  '',
  '▶ Bug 数据已由 n8n 预读取到：' + bugFile,
  '  格式：{status, zentao_url, bug:{...}}  bug 字段在顶层 bug 对象中，无需二次解析',
  '  steps 字段含 HTML，图片已是绝对 URL，可直接 WebFetch 获取',
  '  请先执行：cat ' + bugFile + '  来获取 Bug 详情，无需再调用 fetch 命令。',
  '  （如果文件读取异常，再用 ' + credPrefix + ' python3 ' + skillPy + ' fetch ' + bugId + ' 作为备用）',
  '',
  '▶ 所有 bugfix_flow.py 命令前缀：' + credPrefix,
  '',
  '固定执行顺序（严格遵守）：',
  '1. 读取 ' + bugFile + '   Bug 内容',
  '2. 分析代码，定位根因，修复代码',
  '3. 自测验证（运行相关测试，确认通过）',
  '4. git add <相关文件>（禁止 git add .）',
  '5. git commit',
  '6. 读取 Issue 模板：cat $SKILL_DIR/templates/issue_6d_template.md',
  '   按该模板格式写入 ' + issueDescFile + '，将所有 {{占位符}} 替换为实际内容（必须包含全6个章节，禁止留空占位符）',
  '7. 读取 MR 模板：cat $SKILL_DIR/templates/mr_template.md',
  '   按该模板格式写入 ' + mrDescFile + '，将所有 {{占位符}} 替换为实际内容',
  '   n8n 会自动识别 bug 类型，Claude 无需在文件末尾追加任何额外行。',
  '   n8n 将自动执行 push-branch / create-issue / create-mr，Claude 无需调用',
  '',
  '⚠️ 禁止调用 zentao-premerge-writeback 和 zentao-postmerge-resolve（n8n 自动执行）',
  '⚠️ 只要验证失败，立即停止，在输出中包含 STATUS=FAIL。',
  '',
  '完成后必须在输出末尾（每项单独一行）：',
  'SUMMARY=<一句话总结>',
  '(不要输出 ISSUE_URL/MR_URL，n8n 会自动获取)',
].join('\n');

const ackComment = buildCommentCommand(
  '[AI] AI处理中，自动修复已启动，正在执行 zc-bug-fix 服务器工作流。',
  'ack'
);
const ackCommand = buildCreateCredsCmd() + '\n' + ackComment;


// ── Push / Issue / MR 命令（在此预构建，Execute Command 节点用 $json.xxx 引用）──

const pushCommand = [
  'cd ' + shellSingleQuote(worktreeDir),
  '# Guard: check if there are actual code changes or new commits',
  'if [ -z "$(git status --short)" ] && [ -z "$(git log origin/' + targetBranch + '..HEAD --oneline)" ]; then',
  '  echo "STATUS=PUSH_SKIP"',
  '  echo "SUMMARY=no code changes detected, skip push"',
  '  exit 0',
  'fi',
  'if ZC_BUG_FIX_CONFIG=' + shellSingleQuote(credFile) +
    ' python3 ' + shellSingleQuote(skillPy) + ' push-branch 2>&1; then',
  '  echo "STATUS=PUSH_OK"',
  'else',
  '  echo "STATUS=PUSH_FAIL"',
  'fi',
].join('\n');

const createIssueCommand = [
  'CRED=' + shellSingleQuote(credFile),
  'BUG_ID=' + shellSingleQuote(bugId),
  'DESC=' + shellSingleQuote(issueDescFile),
  'if [ ! -f "$DESC" ]; then',
  '  printf "# Bug #' + bugId + ' AI Fix\\n" > "$DESC"',
  '  printf "AI-generated fix, see MR for details.\\n" >> "$DESC"',
  'fi',
  'ZC_BUG_FIX_CONFIG="$CRED" python3 ' + shellSingleQuote(skillPy) +
    ' create-issue "$BUG_ID" "$DESC" 2>&1',
  'echo "ISSUE_EXIT=$?"',
].join('\n');

const createMrCommand = [
  'CRED=' + shellSingleQuote(credFile),
  'BUG_ID=' + shellSingleQuote(bugId),
  'BRANCH="bugfix/${BUG_ID}"',
  'DESC=' + shellSingleQuote(mrDescFile),
  'if [ ! -f "$DESC" ]; then',
  '  printf "# Bugfix: Bug #' + bugId + '\\n" > "$DESC"',
  '  printf "AI-generated fix, see commits for details.\\n" >> "$DESC"',
  'fi',
  'ZC_BUG_FIX_CONFIG="$CRED" python3 ' + shellSingleQuote(skillPy) +
    ' create-mr "$BUG_ID" "$BRANCH" "$DESC" 2>&1',
  'echo "MR_EXIT=$?"',
].join('\n');

const earlyFailCommand = [
  'CRED=' + shellSingleQuote(credFile),
  'BUG_ID=' + shellSingleQuote(bugId),
  'SKILL_PY=' + shellSingleQuote(skillPy),
  'TMP=/tmp/zentao-early-fail-' + bugId + '.txt',
  'echo ' + shellSingleQuote('AI fix failed: no code changes generated or fix validation failed.') + ' > "$TMP"',
  'ZC_BUG_FIX_CONFIG="$CRED" python3 "$SKILL_PY" zentao-comment "$BUG_ID" "$TMP" 2>/dev/null || true',
  'rm -f "$TMP"',
  'echo "STATUS=EARLY_FAIL_DONE"',
].join('\n');





const claudeCommand = (setupLines.length && !setupLines[0].includes('STATUS=FAIL'))
  ? [
      'cd ' + shellSingleQuote(worktreeDir),
      "printf '%s' " + shellSingleQuote(prompt) + ' | claude --print --settings /root/.claude/skills/zc-bug-fix/n8n-settings.json 2>&1',
    ].join('\n')
  : 'echo STATUS=FAIL && echo SUMMARY=setup failed, claude not started';

// codexCommand for Codex执行 node (same prompt, Codex CLI)
const promptFile   = worktreeDir + '/.ai-fix/codex-prompt.txt';
const codexCommand = (setupLines.length && !setupLines[0].includes('STATUS=FAIL'))
  ? [
      'printf \'%s\' ' + shellSingleQuote(prompt) + ' > ' + shellSingleQuote(promptFile),
      'cd ' + shellSingleQuote(worktreeDir),
      'codex --full-auto < ' + shellSingleQuote(promptFile),
      'CODE=$?',
      'rm -f ' + shellSingleQuote(promptFile),
      'exit $CODE',
    ].join('\n')
  : 'echo STATUS=FAIL && echo SUMMARY=setup failed, codex not started';

const checkFixCommand = (setupLines.length && !setupLines[0].includes('STATUS=FAIL'))
  ? [
      'cd ' + shellSingleQuote(worktreeDir),
      'if git log origin/' + targetBranch + '..HEAD --oneline 2>/dev/null | grep -q .; then',
      '  echo "STATUS=VALID"',
      '  echo "SUMMARY=code changes detected"',
      'elif [ -n "$(git status --short 2>/dev/null)" ]; then',
      '  echo "STATUS=VALID"',
      '  echo "SUMMARY=uncommitted changes detected"',
      'else',
      '  echo "STATUS=INVALID"',
      '  echo "SUMMARY=no code changes in worktree"',
      'fi',
    ].join('\n')
  : 'echo "STATUS=INVALID" && echo "SUMMARY=setup failed"';

return {
  claudeCommand,
  checkFixCommand,
  codexCommand,
  earlyFailCommand,
  bugId,
  productId,
  projectKey,
  resolvedProject,
  sourceRepo,
  worktreeDir,
  credFile,
  bugFile,
  ackCommand,
  setupCommand,
  prompt,
  pushCommand,
  createIssueCommand,
  createMrCommand,
};

const bugId    = String($('准备执行').item.json.bugId    || '').trim();
const credFile = String($('准备执行').item.json.credFile || '');
const skillPy  = '/root/.claude/skills/zc-bug-fix/scripts/bugfix_flow.py';

// AI output — unified via 合并AI输出 node
const claudeOutput = String($('合并AI输出').item?.json?.aiResult || '');
const summaryMatch = claudeOutput.match(/^SUMMARY=(.*)$/m);
const summary      = summaryMatch ? summaryMatch[1].trim() : 'AI修复流程执行完成';

// Issue URL — parse web_url from GitLab API JSON
const issueStdout = String($('创建 Issue').item?.json?.stdout || '');
let issueUrl = '';
try {
  const issueEnd = issueStdout.lastIndexOf('\nISSUE_EXIT=');
  const issueStr = issueEnd > 0 ? issueStdout.substring(0, issueEnd).trim() : issueStdout.trim();
  issueUrl = JSON.parse(issueStr).web_url || '';
} catch(e) {
  const m = issueStdout.match(/"web_url"\s*:\s*"([^"]+)"/);
  issueUrl = m ? m[1] : '';
}

// MR URL — parse web_url from GitLab API JSON
const mrStdout = String($('创建 MR').item?.json?.stdout || '');
let mrUrl = '';
try {
  const mrEnd = mrStdout.lastIndexOf('\nMR_EXIT=');
  const mrStr = mrEnd > 0 ? mrStdout.substring(0, mrEnd).trim() : mrStdout.trim();
  mrUrl = JSON.parse(mrStr).web_url || '';
} catch(e) {
  const m = mrStdout.match(/"web_url"\s*:\s*"([^"]+)"/);
  mrUrl = m ? m[1] : '';
}

// BUG_TYPE — from OpenAI LLM classification node
const ALLOWED_BUG_TYPES = [
  "需求不清问题", "需求错误问题",
  "设计_系统整体设计问题", "设计_功能间接口问题", "设计_功能交互问题",
  "设计_边界值设计问题", "设计_流程逻辑设计问题", "设计_算法设计问题",
  "编码_流程逻辑实现问题", "编码_编程规范语法问题", "编码_编程规范内存问题",
  "编码_编程规范初始化", "编码_编程规范函数用错", "编码_编程规范指针调用",
  "编码_代码合并问题", "编码_模块间接口问题", "编码_库使用问题", "编码_库修改问题",
  "编码-内核保护机制问题"
];
const FALLBACK_BUG_TYPE = '编码_流程逻辑实现问题';
const rawClassified = String($('提取BugType').item?.json?.classifiedBugType || '');
const bugType      = ALLOWED_BUG_TYPES.includes(rawClassified) ? rawClassified : FALLBACK_BUG_TYPE;
const bugTypeValid = ALLOWED_BUG_TYPES.includes(rawClassified);

// isSuccess
const pushOut = String($('推送分支').item?.json?.stdout || '');
const pushOk  = !pushOut.includes('STATUS=PUSH_FAIL');
const isSuccess = !!summaryMatch
  && !/\bSTATUS=FAIL\b/.test(claudeOutput)
  && pushOk;

function shellSingleQuote(v) {
  return "'" + String(v).replace(/'/g, "'\\''") + "'";
}

function buildSuccessCommand() {
  if (!/^\d+$/.test(bugId)) return 'echo "STATUS=COMMENT_SKIPPED"';
  const credPrefix = 'ZC_BUG_FIX_CONFIG=' + shellSingleQuote(credFile);
  if (mrUrl) {
    const parts = [
      credPrefix + ' python3 ' + skillPy +
        ' zentao-premerge-writeback ' +
        shellSingleQuote(bugId) + ' ' +
        shellSingleQuote(bugType) + ' ' +
        shellSingleQuote(issueUrl || '') + ' ' +
        shellSingleQuote(mrUrl),
    ];
    if (!bugTypeValid) {
      const warnFile = '/tmp/zentao-warn-' + bugId + '.txt';
      parts.push(
        'echo ' + shellSingleQuote('BUG_TYPE fallback: ' + bugType) + ' > ' + warnFile,
        credPrefix + ' python3 ' + skillPy + ' zentao-comment ' +
          shellSingleQuote(bugId) + ' ' + warnFile + ' 2>/dev/null || true',
        'rm -f ' + warnFile,
      );
    }
    parts.push('rm -f ' + shellSingleQuote(credFile), 'echo "STATUS=WRITEBACK_DONE"');
    return parts.join('\n');
  } else {
    const tmp = '/tmp/zentao-result-' + bugId + '.txt';
    return [
      'echo ' + shellSingleQuote('AI fix done (no MR created, check manually): ' + summary) + ' > ' + tmp,
      credPrefix + ' python3 ' + skillPy + ' zentao-comment ' +
        shellSingleQuote(bugId) + ' ' + tmp + ' 2>/dev/null || true',
      'rm -f ' + tmp, 'rm -f ' + shellSingleQuote(credFile), 'echo "STATUS=COMMENT_DONE"',
    ].join('\n');
  }
}

function buildFailCommand() {
  if (!/^\d+$/.test(bugId)) return 'echo "STATUS=COMMENT_SKIPPED"';
  const credPrefix = 'ZC_BUG_FIX_CONFIG=' + shellSingleQuote(credFile);
  const tmp = '/tmp/zentao-result-' + bugId + '.txt';
  let msg = 'AI fix failed: ' + summary;
  if (mrUrl) msg += '\nMR created: ' + mrUrl;
  return [
    'echo ' + shellSingleQuote(msg) + ' > ' + tmp,
    credPrefix + ' python3 ' + skillPy + ' zentao-comment ' +
      shellSingleQuote(bugId) + ' ' + tmp + ' 2>/dev/null || true',
    'rm -f ' + tmp, 'rm -f ' + shellSingleQuote(credFile), 'echo "STATUS=COMMENT_DONE"',
  ].join('\n');
}

return {
  bugId, isSuccess, summary, issueUrl, mrUrl, bugType, bugTypeValid,
  successCommentCommand: buildSuccessCommand(),
  failCommentCommand:    buildFailCommand(),
  rawOutput: claudeOutput.slice(0, 2000),
};

const stdout   = String($input.item.json.stdout || '');
const bugId    = String($('准备执行').item.json.bugId    || '').trim();
const credFile = String($('准备执行').item.json.credFile || '');

const summaryMatch = stdout.match(/^SUMMARY=(.*)$/m);
const summary = summaryMatch ? summaryMatch[1].trim() : '环境准备失败（worktree 创建失败）';

function shellSingleQuote(v) {
  return "'" + String(v).replace(/'/g, "'\\''") + "'";
}

function buildCommentCommand(commentText, tmpSuffix) {
  if (!/^\d+$/.test(bugId)) return 'echo "STATUS=COMMENT_SKIPPED"';
  const tmp = '/tmp/zentao-' + tmpSuffix + '-' + bugId + '.txt';
  return [
    'echo ' + shellSingleQuote(commentText) + ' > ' + tmp,
    'ZC_BUG_FIX_CONFIG=' + shellSingleQuote(credFile) +
      ' python3 /root/.claude/skills/zc-bug-fix/scripts/bugfix_flow.py zentao-comment ' +
      shellSingleQuote(bugId) + ' ' + tmp + ' 2>/dev/null || true',
    'rm -f ' + tmp,
    'rm -f ' + shellSingleQuote(credFile),   // ← 清理凭据文件
    'echo "STATUS=COMMENT_DONE"'
  ].join('\n');
}

return {
  bugId,
  isSuccess: false,
  summary,
  successCommentCommand: '',
  failCommentCommand: buildCommentCommand('❌ 环境准备失败：' + summary, 'setup-fail'),
};

// ===========================================================================
//  Project Config  --  add / remove projects here
//
//  Columns:
//    [0] ZenTao project name  (body.project / body.projectName)
//    [1] Absolute repo path on the server
//    [2] GitLab project numeric ID
//    [3] MR assignee username  (empty => defaults.projectOwner)
//    [4] Base branch           (empty => defaults.targetBranch)
//    [5] ZenTao product ID     (number inside body.product, e.g. ",52," => "52")
//
//  At least one of [0] or [5] must be filled per row.
// ===========================================================================

//         [0] name                  [1] repo path                             [2] glId  [3] owner  [4] branch   [5] productId
const table = [
  ["power_quality_module", "/root/git/power_quality_module", "799", "wangrui", "develop", "52"],
  // ["proj-b",            "/root/git/proj-b",               "15", "",      "main",    "10"],
];

const defaults = {
  projectOwner: "developer",
  targetBranch: "develop",
  worktreeBase: "/tmp/n8n-worktrees",
};

// --- generated maps (do not edit) ---
const projects     = {};
const productIdMap = {};

for (const [name, repoPath, gitlabProjectId, projectOwner, targetBranch, productId] of table) {
  const entry = {
    repoPath,
    gitlabProjectId,
    projectOwner: projectOwner || undefined,
    targetBranch: targetBranch || undefined,
    displayName:  name || undefined,
  };
  if (name)      projects[name]                         = entry;
  if (productId) productIdMap[String(productId).trim()] = entry;
}

return {
  ...$input.item.json,
  _config: { projects, productIdMap, defaults },
};

// ======================
